import socket, concurrent.futures as cf
prefixes = ["192.168.209.","192.168.210.","192.168.207.","192.168.200.","10.0.0.","172.18.0.","172.17.0.","192.168.224."]
def probe(t):
    ip, port = t
    s = socket.socket(); s.settimeout(0.3)
    try:
        if s.connect_ex((ip, port)) == 0:
            return (ip, port)
    except Exception:
        pass
    finally:
        s.close()
    return None
targets = []
for p in prefixes:
    for i in range(1, 255):
        targets.append((f"{p}{i}", 80))
with cf.ThreadPoolExecutor(max_workers=128) as ex:
    for r in ex.map(probe, targets):
        if r:
            print("OPEN:", r[0], r[1])
print("scan done")
EOF"}

